package org.eclipse.kura.management.agent.firewall;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.eclipse.kura.management.agent.model.FirewallRuleSet;
import org.eclipse.kura.management.agent.model.FirewallTable;
import org.junit.jupiter.api.Test;

class IptablesSaveParserTest {

    @Test
    void parsesTablesChainsAndRules() {
        String save = """
                # generated by iptables-save
                *filter
                :INPUT DROP [12:720]
                :FORWARD DROP [0:0]
                :OUTPUT ACCEPT [4:320]
                :input-kura - [0:0]
                -I INPUT -j input-kura
                -A input-kura -p tcp -s 0.0.0.0/0 --dport 22 -j ACCEPT
                COMMIT
                *nat
                :PREROUTING ACCEPT [0:0]
                :POSTROUTING ACCEPT [0:0]
                -I PREROUTING -j prerouting-kura
                COMMIT
                """;

        FirewallRuleSet ruleSet = new IptablesSaveParser().parse("ipv4", save);

        assertEquals("ipv4", ruleSet.ipVersion());
        assertEquals(2, ruleSet.tables().size());

        FirewallTable filter = ruleSet.tables().get(0);
        assertEquals("filter", filter.name());
        assertEquals(4, filter.chains().size());
        assertEquals("INPUT", filter.chains().get(0).name());
        assertEquals("DROP", filter.chains().get(0).policy());
        assertEquals("[12:720]", filter.chains().get(0).counters());
        assertEquals(2, filter.rules().size());
        assertEquals("-I", filter.rules().get(0).action());
        assertEquals("INPUT", filter.rules().get(0).chain());
        assertEquals("-j input-kura", filter.rules().get(0).expression());
        assertEquals("-p tcp -s 0.0.0.0/0 --dport 22 -j ACCEPT", filter.rules().get(1).expression());

        FirewallTable nat = ruleSet.tables().get(1);
        assertEquals("nat", nat.name());
        assertEquals(2, nat.chains().size());
        assertEquals(1, nat.rules().size());
    }

    @Test
    void keepsOpenTableWhenCommitIsMissing() {
        String save = """
                *mangle
                :PREROUTING ACCEPT [0:0]
                -A PREROUTING -j prerouting-kura
                """;

        FirewallRuleSet ruleSet = new IptablesSaveParser().parse("ipv6", save);

        assertEquals(1, ruleSet.tables().size());
        assertEquals("mangle", ruleSet.tables().get(0).name());
        assertEquals("ipv6", ruleSet.ipVersion());
    }
}
